create table if not exists authorization_decisions(decision_id uuid primary key,idempotency_key varchar(128) not null unique,payment_id varchar(128) not null,issuer_id varchar(128) not null,amount_minor bigint not null,currency char(3) not null,status varchar(32) not null,reason varchar(64) not null,created_at timestamptz not null default now()); create table if not exists outbox_events(event_id uuid primary key,event_type varchar(128) not null,aggregate_id varchar(128) not null,payload text not null,created_at timestamptz not null default now(),published_at timestamptz); create table if not exists reconciliation_items(item_id uuid primary key,payment_id varchar(128) not null,expected_status varchar(32) not null,observed_status varchar(32),amount_minor bigint not null,created_at timestamptz not null default now(),processed_at timestamptz); create table if not exists reconciliation_results(item_id uuid primary key,payment_id varchar(128) not null,match_status varchar(32) not null,delta_minor bigint not null,processed_at timestamptz not null default now());